function getPageLang() {
  var p = window.location.pathname;
  if (p.startsWith('/es/')) return 'es';
  if (p.startsWith('/fr/')) return 'fr';
  if (p.startsWith('/de/')) return 'de';
  return 'en';
}

function t(key) {
  var lang = getPageLang();
  return (I18N[lang] && I18N[lang][key]) || I18N.en[key] || key;
}

// ===== Custom Toast Notification =====
function showToast(type, title, message) {
  // Remove any existing toast
  var existing = document.getElementById('customToastOverlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'customToastOverlay';

  var iconSvg = type === 'success'
    ? '<svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#2D6A4F" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>'
    : '<svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#C45C26" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>';

  overlay.innerHTML =
    '<div class="custom-toast-card">' +
      '<div class="custom-toast-icon">' + iconSvg + '</div>' +
      '<h3 class="custom-toast-title">' + title + '</h3>' +
      '<p class="custom-toast-msg">' + message + '</p>' +
      '<button class="custom-toast-btn" id="customToastClose">' + t('closeBtn') + '</button>' +
    '</div>';

  var style = document.createElement('style');
  style.id = 'customToastStyle';
  if (!document.getElementById('customToastStyle')) {
    style.textContent =
      '#customToastOverlay{position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:99999;display:flex;align-items:center;justify-content:center;animation:ctFadeIn .3s ease}' +
      '.custom-toast-card{background:#fff;border-radius:16px;padding:40px 32px;max-width:400px;width:90%;text-align:center;box-shadow:0 24px 80px rgba(0,0,0,0.25);animation:ctSlideUp .35s cubic-bezier(0.16,1,0.3,1)}' +
      '.custom-toast-icon{margin-bottom:20px;display:flex;justify-content:center}' +
      '.custom-toast-title{font-size:1.6rem;font-weight:700;margin:0 0 10px;color:#1a1a1a}' +
      '.custom-toast-msg{font-size:1.05rem;color:#666;line-height:1.6;margin:0 0 28px}' +
      '.custom-toast-btn{background:#C45C26;color:#fff;border:none;padding:13px 40px;border-radius:10px;font-size:1rem;font-weight:600;cursor:pointer;transition:opacity .2s,transform .1s}' +
      '.custom-toast-btn:hover{opacity:.88}' +
      '.custom-toast-btn:active{transform:scale(0.96)}' +
      '@keyframes ctFadeIn{from{opacity:0}to{opacity:1}}' +
      '@keyframes ctSlideUp{from{transform:translateY(30px) scale(0.96);opacity:0}to{transform:translateY(0) scale(1);opacity:1}}';
    document.head.appendChild(style);
  } else {
    style.remove();
  }

  document.body.appendChild(overlay);

  function closeToast() {
    overlay.style.animation = 'ctFadeIn .25s ease reverse';
    setTimeout(function() { overlay.remove(); }, 200);
  }

  document.getElementById('customToastClose').addEventListener('click', closeToast);
  overlay.addEventListener('click', function(e) { if (e.target === overlay) closeToast(); });
  document.addEventListener('keydown', function onKey(e) {
    if (e.key === 'Escape') { closeToast(); document.removeEventListener('keydown', onKey); }
  });

  // Auto-close after 5 seconds for success
  if (type === 'success') {
    setTimeout(closeToast, 5000);
  }
}

(function() {
  'use strict';

  // Scroll reveal animation
  const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
  };

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
      }
    });
  }, observerOptions);

  document.querySelectorAll('.fade-in').forEach(el => {
    observer.observe(el);
  });

  // Navbar scroll effect
  const navbar = document.querySelector('.navbar');
  if (navbar) {
    window.addEventListener('scroll', () => {
      const currentScroll = window.pageYOffset;
      if (currentScroll > 100) {
        navbar.style.boxShadow = '0 2px 20px rgba(0,0,0,0.06)';
      } else {
        navbar.style.boxShadow = 'none';
      }
    });
  }

  // Smooth scroll for anchor links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      e.preventDefault();
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        const offset = 80;
        const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - offset;
        window.scrollTo({
          top: targetPosition,
          behavior: 'smooth'
        });
      }
    });
  });

  // Mobile menu toggle
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');

  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      const isExpanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';
      mobileMenuBtn.setAttribute('aria-expanded', !isExpanded);

      if (!isExpanded) {
        navLinks.style.display = 'flex';
        navLinks.style.flexDirection = 'column';
        navLinks.style.position = 'absolute';
        navLinks.style.top = '64px';
        navLinks.style.left = '0';
        navLinks.style.right = '0';
        navLinks.style.background = 'rgba(250, 250, 248, 0.98)';
        navLinks.style.padding = '1.5rem 2rem';
        navLinks.style.boxShadow = '0 8px 24px rgba(0,0,0,0.08)';
        navLinks.style.gap = '1rem';
        navLinks.style.zIndex = '999';
        navLinks.style.borderBottom = '1px solid var(--rule)';
      } else {
        navLinks.style.display = '';
        navLinks.style.flexDirection = '';
        navLinks.style.position = '';
        navLinks.style.top = '';
        navLinks.style.left = '';
        navLinks.style.right = '';
        navLinks.style.background = '';
        navLinks.style.padding = '';
        navLinks.style.boxShadow = '';
        navLinks.style.gap = '';
        navLinks.style.zIndex = '';
        navLinks.style.borderBottom = '';
      }
    });
  }

  // ===== Modal / Popup Form =====
  const modalHTML = `
    <div class="modal-overlay" id="inquiryModal" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <div class="modal">
        <div class="modal-header">
          <h2 id="modalTitle">Get a Free Quote</h2>
          <button type="button" class="modal-close" aria-label="Close" id="modalClose">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>
        <div class="modal-body">
          <form class="modal-form" id="inquiryForm" novalidate>
            <div class="form-group">
              <label for="inquiryName">Name <span class="required-mark">*</span></label>
              <input type="text" id="inquiryName" name="name" required placeholder="Your name">
            </div>
            <div class="form-group">
              <label for="inquiryCountry">Country <span class="required-mark">*</span></label>
              <input type="text" id="inquiryCountry" name="country" required placeholder="e.g. USA, Germany, Australia">
            </div>
            <div class="form-group">
              <label for="inquiryEmail">Email <span class="required-mark">*</span></label>
              <input type="email" id="inquiryEmail" name="email" required placeholder="your@email.com">
            </div>
            <div class="form-group">
              <label for="inquiryPhone">Phone / WhatsApp</label>
              <input type="text" id="inquiryPhone" name="phone" placeholder="+86 123 4567 8900">
            </div>
            <div class="form-group">
              <label for="inquiryProduct">Product Type</label>
              <select id="inquiryProduct" name="productType">
                <option value="">Select a product type</option>
                <option value="canvas-bags">Canvas Bags</option>
                <option value="non-woven-bags">Non-Woven Bags</option>
                <option value="drawstring-bags">Drawstring Bags</option>
                <option value="felt-bags">Felt Bags</option>
                <option value="not-sure">Not Sure / Need Recommendation</option>
              </select>
            </div>
            <div class="form-group">
              <label for="inquiryQuantity">Estimated Quantity</label>
              <select id="inquiryQuantity" name="quantity">
                <option value="">Select quantity</option>
                <option value="100-499">100 - 499 pcs</option>
                <option value="500-999">500 - 999 pcs</option>
                <option value="1000-2999">1,000 - 2,999 pcs</option>
                <option value="3000-9999">3,000 - 9,999 pcs</option>
                <option value="10000+">10,000+ pcs</option>
              </select>
            </div>
            <div class="form-group">
              <label for="inquiryMessage">Message</label>
              <textarea id="inquiryMessage" name="message" rows="3" placeholder="Describe your needs: size, print content, etc."></textarea>
            </div>
            <input type="hidden" id="inquiryLang" name="lang" value="en">
            <button type="submit" class="btn btn-primary modal-submit" id="modalSubmit">Get a Free Quote</button>
          </form>
          <div class="modal-success" id="modalSuccess" style="display:none;">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#2D6A4F" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
            <h3 id="modalSuccessTitle">Thank you!</h3>
            <p id="modalSuccessMsg">We'll contact you within 24 hours with your quote.</p>
          </div>
          <div class="modal-error" id="modalError" style="display:none;">
            <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#C45C26" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
            <h3 id="modalErrorTitle">Submission Failed</h3>
            <p id="modalErrorText">Submission failed. Please try again or call us directly.</p>
          </div>
        </div>
      </div>
    </div>
  `;

  // Inject modal into body
  document.body.insertAdjacentHTML('beforeend', modalHTML);

  const modal = document.getElementById('inquiryModal');
  const modalClose = document.getElementById('modalClose');
  const inquiryForm = document.getElementById('inquiryForm');
  const modalSuccess = document.getElementById('modalSuccess');
  const modalError = document.getElementById('modalError');
  const modalErrorText = document.getElementById('modalErrorText');
  const modalSubmit = document.getElementById('modalSubmit');

  function openModal() {
    // Detect current language from URL path
    const path = window.location.pathname;
    let lang = 'en';
    if (path.startsWith('/es/')) lang = 'es';
    else if (path.startsWith('/fr/')) lang = 'fr';
    else if (path.startsWith('/de/')) lang = 'de';
    document.getElementById('inquiryLang').value = lang;

    // Update button and success/error texts to current language
    modalSubmit.textContent = t('submitBtn');
    document.getElementById('modalSuccessTitle').textContent = t('successTitle');
    document.getElementById('modalSuccessMsg').textContent = t('successMsg');
    document.getElementById('modalErrorTitle').textContent = t('errorTitle');

    modal.classList.add('active');
    document.body.style.overflow = 'hidden';
    document.getElementById('inquiryName').focus();
  }

  function closeModal() {
    modal.classList.remove('active');
    document.body.style.overflow = '';
    // Reset form after animation
    setTimeout(() => {
      inquiryForm.style.display = '';
      modalSuccess.style.display = 'none';
      modalError.style.display = 'none';
      inquiryForm.reset();
      modalSubmit.disabled = false;
      modalSubmit.textContent = t('submitBtn');
    }, 300);
  }

  // Bind to all CTA buttons (nav CTA, bottom CTA section, hero buttons)
  document.querySelectorAll('.nav-cta, .cta-section .btn, .hero-buttons .btn-primary.open-modal').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      openModal();
    });
  });

  modalClose.addEventListener('click', closeModal);

  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeModal();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.classList.contains('active')) {
      closeModal();
    }
  });

  // Form submission
  inquiryForm.addEventListener('submit', async function(e) {
    e.preventDefault();

    const name = document.getElementById('inquiryName').value.trim();
    const email = document.getElementById('inquiryEmail').value.trim();
    const country = document.getElementById('inquiryCountry').value.trim();
    const phone = document.getElementById('inquiryPhone').value.trim();
    const productType = document.getElementById('inquiryProduct').value;
    const quantity = document.getElementById('inquiryQuantity').value;
    const message = document.getElementById('inquiryMessage').value.trim();

    if (!name || !country || !email) {
      if (!name) document.getElementById('inquiryName').focus();
      else if (!country) document.getElementById('inquiryCountry').focus();
      else if (!email) document.getElementById('inquiryEmail').focus();
      return;
    }

    // Submit to D1 via /api/inquiry
    modalSubmit.disabled = true;
    modalSubmit.textContent = t('submitting');

    const formData = new FormData();
    formData.append('name', name);
    formData.append('email', email);
    formData.append('country', country);
    if (phone) formData.append('phone', phone);
    if (productType) formData.append('productType', productType);
    if (quantity) formData.append('quantity', quantity);
    if (message) formData.append('message', message);

    try {
      const response = await fetch('/api/inquiry', {
        method: 'POST',
        body: formData
      });

      const result = await response.json();

      if (result.success) {
        inquiryForm.style.display = 'none';
        modalSuccess.style.display = 'block';
      } else {
        modalErrorText.textContent = result.error || 'Submission failed. Please try again or call us directly.';
        inquiryForm.style.display = 'none';
        modalError.style.display = 'block';
      }
    } catch (err) {
      modalErrorText.textContent = 'Network error. Please try again or contact us by phone.';
      inquiryForm.style.display = 'none';
      modalError.style.display = 'block';
    }

    modalSubmit.disabled = false;
    modalSubmit.textContent = t('submitBtn');
  }); // end addEventListener submit

  // Image lightbox — hover loads full image, click opens fullscreen
  const lightboxHTML = '<div class="lightbox-overlay" id="imageLightbox"><button class="lightbox-close" id="lightboxClose" aria-label="Close">&times;</button><img src="" alt="" id="lightboxImg"></div>';
  document.body.insertAdjacentHTML('beforeend', lightboxHTML);

  const lightbox = document.getElementById('imageLightbox');
  const lightboxImg = document.getElementById('lightboxImg');
  const lightboxClose = document.getElementById('lightboxClose');

  function openLightbox(src, alt) {
    lightboxImg.src = src;
    lightboxImg.alt = alt;
    lightbox.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
  function closeLightbox() {
    lightbox.classList.remove('active');
    lightboxImg.src = '';
    document.body.style.overflow = '';
  }

  lightboxClose.addEventListener('click', closeLightbox);
  lightbox.addEventListener('click', function(e) {
    if (e.target === lightbox) closeLightbox();
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && lightbox.classList.contains('active')) closeLightbox();
  });

  // Lazy thumb hover: ONLY for thumbnail images (not main image)
  document.querySelectorAll('.gallery-thumb img.lazy-thumb').forEach(function(img) {
    img.addEventListener('mouseenter', function() {
      var full = this.dataset.full;
      if (full && this.src !== full) {
        this.src = full;
        this.style.cursor = 'zoom-in';
      }
    });
  });

  // Lightbox click: lazy-thumb images + gallery main image
  document.querySelectorAll('img.lazy-thumb, .gallery-main img').forEach(function(img) {
    img.addEventListener('click', function() {
      var src = this.dataset.full || this.src;
      openLightbox(src, this.alt);
    });
  });

})();

// ===== Language Suggestion Popup (frontend IP detection) =====
(function() {
  // Only on root page, skip sub-language pages
  if (window.location.pathname !== '/') return;

  // Already has preference cookie?
  if (document.cookie.includes('preferred_lang=') || document.cookie.includes('lang_dismissed=')) {
    // If preferred_lang cookie exists, redirect
    var m = document.cookie.match(/(?:^|;\s*)preferred_lang=(es|fr|de)/);
    if (m) { window.location.href = '/' + m[1] + '/'; }
    return;
  }

  var COUNTRY_LANG = {
    ES:'es',MX:'es',AR:'es',CO:'es',CL:'es',PE:'es',VE:'es',EC:'es',GT:'es',
    CU:'es',BO:'es',DO:'es',HN:'es',PY:'es',SV:'es',NI:'es',CR:'es',PA:'es',UY:'es',GQ:'es',
    FR:'fr',BE:'fr',LU:'fr',MC:'fr',SN:'fr',CI:'fr',ML:'fr',BF:'fr',NE:'fr',TD:'fr',
    GN:'fr',BI:'fr',DJ:'fr',RW:'fr',MG:'fr',KM:'fr',CG:'fr',CD:'fr',
    DE:'de',AT:'de',CH:'de',LI:'de'
  };

  var COUNTRY_NAMES = {
    ES:'Spain',MX:'Mexico',AR:'Argentina',CO:'Colombia',CL:'Chile',PE:'Peru',
    VE:'Venezuela',EC:'Ecuador',GT:'Guatemala',CU:'Cuba',BO:'Bolivia',DO:'Dominican Republic',
    HN:'Honduras',PY:'Paraguay',SV:'El Salvador',NI:'Nicaragua',CR:'Costa Rica',PA:'Panama',UY:'Uruguay',GQ:'Equatorial Guinea',
    FR:'France',BE:'Belgium',LU:'Luxembourg',MC:'Monaco',SN:'Senegal',CI:'Ivory Coast',
    ML:'Mali',BF:'Burkina Faso',NE:'Niger',TD:'Chad',GN:'Guinea',BI:'Burundi',
    DJ:'Djibouti',RW:'Rwanda',MG:'Madagascar',KM:'Comoros',CG:'Congo',CD:'DR Congo',
    DE:'Germany',AT:'Austria',CH:'Switzerland',LI:'Liechtenstein'
  };

  var langNames = { es: 'Español', fr: 'Français', de: 'Deutsch' };

  // Detect country via free API (cloudflare fallback)
  fetch('https://ipapi.co/json/').then(function(r){ return r.json(); }).then(function(data){
    var cc = (data.country_code || '').toUpperCase();
    var lang = COUNTRY_LANG[cc];
    if (!lang) return;

    var country = COUNTRY_NAMES[cc] || data.country_name || cc;
    var langName = langNames[lang] || lang;

    // Double-check cookie wasn't set during async call
    if (document.cookie.includes('preferred_lang=') || document.cookie.includes('lang_dismissed=')) return;

    showPopup(lang, country, langName);
  }).catch(function(){
    // API failed, try Cloudflare trace as fallback
    fetch('https://www.cloudflare.com/cdn-cgi/trace').then(function(r){ return r.text(); }).then(function(text){
      var m = text.match(/loc=([A-Z]{2})/);
      if (!m) return;
      var cc = m[1];
      var lang = COUNTRY_LANG[cc];
      if (!lang) return;
      var country = COUNTRY_NAMES[cc] || cc;
      var langName = langNames[lang] || lang;
      if (document.cookie.includes('preferred_lang=') || document.cookie.includes('lang_dismissed=')) return;
      showPopup(lang, country, langName);
    }).catch(function(){});
  });

  function showPopup(lang, country, langName) {
    var overlay = document.createElement('div');
    overlay.id = 'langSuggestOverlay';
    overlay.innerHTML =
      '<div class="lang-suggest-modal">' +
        '<div class="lang-suggest-icon">' +
          '<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#C45C26" stroke-width="1.5">' +
            '<circle cx="12" cy="12" r="10"/>' +
            '<path d="M2 12h20"/>' +
            '<path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>' +
          '</svg>' +
        '</div>' +
        '<h3>Switch Language?</h3>' +
        '<p>We detected you may be visiting from <strong>' + country + '</strong>.</p>' +
        '<p>Would you like to view this site in <strong>' + langName + '</strong>?</p>' +
        '<div class="lang-suggest-buttons">' +
          '<button class="btn btn-primary" id="langSwitchBtn">Switch to ' + langName + '</button>' +
          '<button class="btn btn-secondary" id="langStayBtn">Stay in English</button>' +
        '</div>' +
      '</div>';

    var style = document.createElement('style');
    style.textContent =
      '#langSuggestOverlay{position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:center;justify-content:center;animation:fadeIn .25s ease}' +
      '.lang-suggest-modal{background:#fff;border-radius:12px;padding:32px 28px;max-width:420px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.3);animation:slideUp .3s ease}' +
      '.lang-suggest-icon{margin-bottom:16px}' +
      '.lang-suggest-modal h3{font-size:1.5rem;margin:0 0 12px;color:#1a1a1a}' +
      '.lang-suggest-modal p{margin:6px 0;color:#555;line-height:1.5}' +
      '.lang-suggest-buttons{display:flex;gap:12px;justify-content:center;margin-top:24px;flex-wrap:wrap}' +
      '.lang-suggest-buttons .btn{padding:12px 24px;border-radius:8px;font-size:1rem;cursor:pointer;border:none;transition:opacity .2s}' +
      '.lang-suggest-buttons .btn-primary{background:#C45C26;color:#fff}' +
      '.lang-suggest-buttons .btn-secondary{background:#f0f0f0;color:#333}' +
      '.lang-suggest-buttons .btn:hover{opacity:.85}' +
      '@keyframes fadeIn{from{opacity:0}to{opacity:1}}' +
      '@keyframes slideUp{from{transform:translateY(20px);opacity:0}to{transform:translateY(0);opacity:1}}';

    document.head.appendChild(style);
    document.body.appendChild(overlay);

    function dismiss() { overlay.remove(); style.remove(); }

    document.getElementById('langSwitchBtn').addEventListener('click', function() {
      document.cookie = 'preferred_lang=' + lang + '; Path=/; Max-Age=604800; SameSite=Lax';
      window.location.href = '/' + lang + '/';
    });

    document.getElementById('langStayBtn').addEventListener('click', function() {
      document.cookie = 'lang_dismissed=1; Path=/; Max-Age=604800; SameSite=Lax';
      dismiss();
    });

    overlay.addEventListener('click', function(e) {
      if (e.target === overlay) {
        document.cookie = 'lang_dismissed=1; Path=/; Max-Age=604800; SameSite=Lax';
        dismiss();
      }
    });

    document.addEventListener('keydown', function onKey(e) {
      if (e.key === 'Escape') {
        document.cookie = 'lang_dismissed=1; Path=/; Max-Age=604800; SameSite=Lax';
        dismiss();
        document.removeEventListener('keydown', onKey);
      }
    });
  }
})();

// Contact page form — submit to D1 via /api/inquiry
  const contactForm = document.querySelector('.contact-form');
  if (contactForm) {
    // Auto-detect language for contact form
    const contactPath = window.location.pathname;
    let contactLang = 'en';
    if (contactPath.startsWith('/es/')) contactLang = 'es';
    else if (contactPath.startsWith('/fr/')) contactLang = 'fr';
    else if (contactPath.startsWith('/de/')) contactLang = 'de';
    const langInput = contactForm.querySelector('input[name="lang"]');
    if (langInput) langInput.value = contactLang;

    contactForm.addEventListener('submit', async function(e) {
      e.preventDefault();

      if (!this.checkValidity()) {
        this.reportValidity();
        return;
      }

      const submitBtn = this.querySelector('button[type="submit"]');
      const originalText = submitBtn.textContent;
      submitBtn.disabled = true;
      submitBtn.textContent = t('submitting');

      const formData = new FormData(this);

      try {
        const response = await fetch('/api/inquiry', {
          method: 'POST',
          body: formData
        });
        const result = await response.json();
        if (result.success) {
          showToast('success', t('successTitle'), t('successMsg'));
          this.reset();
        } else {
          showToast('error', t('errorTitle'), result.error || t('errorMsg'));
        }
      } catch (err) {
        showToast('error', t('errorTitle'), t('networkError'));
      }

      submitBtn.disabled = false;
      submitBtn.textContent = originalText;
    });
  }

  // ===== Media Gallery Tabs =====
  const mediaTabs = document.querySelectorAll('.media-tab');
  const mediaPanels = document.querySelectorAll('.media-panel');

  mediaTabs.forEach(tab => {
    tab.addEventListener('click', () => {
      const target = tab.getAttribute('data-tab');
      mediaTabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      mediaPanels.forEach(p => {
        p.classList.toggle('active', p.getAttribute('data-panel') === target);
      });
    });
  });

  // ===== Lightbox =====
  const lightbox = document.getElementById('lightbox');
  const lightboxMedia = document.getElementById('lightboxMedia');
  const lightboxCaption = document.getElementById('lightboxCaption');
  const lightboxClose = document.getElementById('lightboxClose');

  function openLightbox(src, type, label) {
    lightboxMedia.innerHTML = '';
    if (type === 'video') {
      const video = document.createElement('video');
      video.src = src;
      video.controls = true;
      video.autoplay = true;
      video.style.maxWidth = '90vw';
      video.style.maxHeight = '85vh';
      lightboxMedia.appendChild(video);
    } else {
      const img = document.createElement('img');
      img.src = src;
      img.alt = label || '';
      lightboxMedia.appendChild(img);
    }
    lightboxCaption.textContent = label || '';
    lightbox.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeLightbox() {
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
    const video = lightboxMedia.querySelector('video');
    if (video) {
      video.pause();
      video.src = '';
    }
    lightboxMedia.innerHTML = '';
  }

  document.querySelectorAll('.media-item').forEach(item => {
    item.addEventListener('click', () => {
      const src = item.getAttribute('data-src');
      const type = item.getAttribute('data-type');
      const label = item.getAttribute('data-label');
      openLightbox(src, type, label);
    });
  });

  if (lightboxClose) {
    lightboxClose.addEventListener('click', closeLightbox);
  }

  if (lightbox) {
    lightbox.addEventListener('click', (e) => {
      if (e.target === lightbox) closeLightbox();
    });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lightbox && lightbox.classList.contains('active')) {
      closeLightbox();
    }
  });

  // ===== Amazon-style Image Gallery (hover to swap main image) =====
  document.querySelectorAll('.product-gallery-amazon').forEach(gallery => {
    const mainImg = gallery.querySelector('.gallery-main img');
    const thumbs = gallery.querySelectorAll('.gallery-thumb');
    if (!mainImg || thumbs.length === 0) return;

    // On load: select first thumb, load full image for main
    if (thumbs[0]) {
      thumbs[0].classList.add('active');
      const firstThumbImg = thumbs[0].querySelector('img');
      const firstFull = firstThumbImg ? firstThumbImg.dataset.full : null;
      if (firstFull) mainImg.src = firstFull;
    }

    thumbs.forEach(thumb => {
      // Hover: instantly show thumb, then load full image
      thumb.addEventListener('mouseenter', () => {
        const thumbImg = thumb.querySelector('img');
        if (!thumbImg) return;

        const fullSrc = thumbImg.dataset.full || thumbImg.src;

        // Step 1: instantly swap to thumbnail (no delay)
        mainImg.src = thumbImg.src;
        mainImg.alt = thumbImg.alt;
        thumbs.forEach(t => t.classList.remove('active'));
        thumb.classList.add('active');

        // Step 2: preload full image, then swap when ready
        const preload = new Image();
        preload.onload = function() {
          mainImg.src = fullSrc;
          mainImg.dataset.full = fullSrc;
        };
        preload.src = fullSrc;
      });

      // Click: also swap (for mobile/touch)
      thumb.addEventListener('click', () => {
        const thumbImg = thumb.querySelector('img');
        if (!thumbImg) return;

        const fullSrc = thumbImg.dataset.full || thumbImg.src;

        mainImg.src = fullSrc;
        mainImg.alt = thumbImg.alt;
        thumbs.forEach(t => t.classList.remove('active'));
        thumb.classList.add('active');
      });
    });

    // No mouseleave reset — keep last hovered image active
  });
